package com.dramastudio.service;
import com.dramastudio.entity.Asset; import com.dramastudio.repository.AssetRepository; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service public class AssetService {
 private final AssetRepository assets;private final ProjectService projects;private final JdbcTemplate jdbc;public AssetService(AssetRepository a,ProjectService p,JdbcTemplate j){assets=a;projects=p;jdbc=j;}
 public List<Asset> list(String project,String user){projects.getOwned(project,user);return assets.findByProjectIdAndDeletedAtIsNullOrderByCreatedAtDesc(project);}
 private Asset owned(String id,String user){Asset a=assets.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"资产不存在"));projects.getOwned(a.projectId,user);return a;}
 @Transactional public Asset action(String id,String action,String user){Asset a=owned(id,user);switch(action){case"approve"->{require(List.of("draft","revision"),a);a.contentStatus="approved";}case"request_revision"->{if(a.locked)throw bad("锁定资产不能修改");a.contentStatus="revision";stale(a);}case"reject"->a.contentStatus="rejected";case"select"->{if(a.locked)throw bad("资产已锁定");assets.clearSelection(a.projectId,a.logicalKey);a.selected=true;a.contentStatus="selected";stale(a);}case"lock"->{if(!(a.selected||a.contentStatus.equals("approved")))throw bad("仅 selected/approved 可锁定");a.locked=true;a.contentStatus="locked";}case"unlock"->{a.locked=false;a.contentStatus=a.selected?"selected":"approved";stale(a);}default->throw bad("未知资产操作");}return assets.save(a);}
 private void stale(Asset a){if(a.nodeRunId!=null)jdbc.update("update node_runs set status='STALE',updated_at=? where id in (select nr.id from node_runs nr join workflow_runs wr on wr.id=nr.workflow_run_id where wr.project_id=? and nr.created_at>?)",Instant.now().toString(),a.projectId,a.createdAt);}
 private void require(List<String>s,Asset a){if(!s.contains(a.contentStatus))throw bad("当前状态不允许操作");}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}
}
